 // Affectations enseignant ↔ matière ↔ classe, grille tarifaire
 crud('affectations','affectations',z.object({enseignant_id:N.int(),matiere_id:N.int(),classe_id:N.int(),annee_scolaire:z.string()}),{read:['admin','enseignant'],soft:false,check:d=>{coherence(d.classe_id,d.matiere_id,d.annee_scolaire);const t=db.prepare('SELECT role FROM users WHERE id=? AND deleted_at IS NULL').get(d.enseignant_id);if(!t||t.role!=='enseignant')throw err(400,"L'intervenant doit être un enseignant")}});
